  if(!changed||lesson!==4){raw.ruby='';raw.equippedReadings=[];}raw.attr=lesson===2?(changed?choice.split(':')[1]:'none'):'metal';
  const edge=lesson===4&&['sturdy','backwater'].includes(choice)||lesson===2&&['element:water'].includes(choice);
  const y=survival&&defense?340:edge?340:280;
  const item={...raw,isPlayer:true,isOut:false,readingAbilities:getReadingAbilities(raw),readingAbility:getReadingAbility(raw)};
  const bodyRaw=lesson===3||lesson===1||lesson===2?raw:{...raw,char:'木'};
  const self=KanjiTraits.createBody(bodyRaw,200,y,1,KanjiRules.getPhysics(getKanjiStats(raw)));self.gameData=item;
  const other=piece('人',10,lesson===3&&choice==='一'?275:200,defense?(survival?260:160):lesson===3&&choice==='一'?240:160,false);
  other.gameData.attr=lesson===2&&choice.startsWith('match:')?KanjiAttributes.advantage[choice.split(':')[1]]:lesson===2&&choice.startsWith('weak:')?Object.keys(KanjiAttributes.advantage).find(k=>KanjiAttributes.advantage[k]===choice.split(':')[1]):'none';
  if(lesson===3&&choice==='凹')Body.setAngle(self,notchBack?Math.PI:0);if(lesson===4&&choice==='counter')Body.setAngle(self,Math.PI);
  const baselineRaw=lesson===4?{...raw,ruby:'',equippedReadings:[]}:lesson===3?{...KANJI_DATABASE.find(i=>i.char===choice),level:10,ruby:'',equippedReadings:[]}:lesson===2&&choice.startsWith('element:')?{...KANJI_DATABASE.find(i=>i.char===attrNames[choice.split(':')[1]]),level:10,ruby:'',equippedReadings:[]}:raw;
  const baseStats=getKanjiStats(baselineRaw);if(lesson===2&&choice.startsWith('element:')&&!changed){Body.setMass(self,KanjiRules.getPhysics(baseStats).mass);self.traitBaseMass=self.mass;}if(lesson===3){baseStats.power=Math.round(baseStats.power/(baseStats.trait?.power||1));baseStats.weight=Math.round(baseStats.weight/(baseStats.trait?.weight||1));if(!changed){Body.setMass(self,KanjiRules.getPhysics(baseStats).mass);self.traitBaseMass=self.mass;}}const targetMass=KanjiRules.getPhysics(baseStats).mass*(survival?3:defense?1:4);
  Body.setMass(other,targetMass);other.traitBaseMass=targetMass;
  const bodies=[self,other];
