  if(lesson===2){if(choice.startsWith('element:')){const attr=choice.split(':')[1],count=attr==='wood'?woodHelpers:elementCount-1;$('tutorial-compare-result').textContent='左・'+attrNames[referenceAttribute()]+'属性：'+KanjiElements.catalogue[referenceAttribute()].name+'\n右・同じ属性が'+(count+1)+'体：'+attributeSummary(attr,count);if(attr==='water')$('tutorial-compare-result').textContent=comparison.map((r,n)=>{const from=r.initial.get(r.body),moved=Math.hypot(r.body.position.x-from.x,r.body.position.y-from.y)/radius*100;return (n?'右・同じ属性が'+(count+1)+'体':'左・'+attrNames[referenceAttribute()]+'属性')+'：'+(!n?'動かない':waterInside?'内側 → 発動なし':moved.toFixed(1)+'%戻った（最大'+[16,18,20][count]+'%）');}).join('\n');}else $('tutorial-compare-result').textContent='左：相性なし ×1.00 ／ 右：'+(choice.startsWith('weak:')?'不利 ×0.75':'有利 ×1.45')+'\n同じ位置・レベル・発射で、相手の動きを比較';return;}
