 function launch(){const g=gesture();start=end=null;pointer=null;if(g.moved<22){message(2,'もう少し長く引こう','短い引っ張りでは発射しません。中央から下へ長く引いて離してみよう。');return;}usedSpin=g.spin;if(lesson===1&&Math.abs(g.spin)<.2){message(2,'横にずらしてから引こう','中央の右か左から、下へ引いて回転をつけよう。');return;}const length=Math.hypot(g.vector.x,g.vector.y),force=.08*(getKanjiStats(own.gameData).power/100)*(g.power/120);Body.applyForce(own,own.position,{x:g.vector.x/length*force,y:g.vector.y/length*force});KanjiBattleSkills.onLaunch(own,world.timing.timestamp,{bodies:[own,enemy],arena:{center,radius}});KanjiTraits.onLaunch(own,world.timing.timestamp,g.spin);state='flight';elapsed=0;message(3,'相手を場外へ落とそう','引いた方向と反対へ発射！赤い相手が土俵の外へ出れば成功です。');}
