 const canvas=$('tutorial-canvas');canvas.tabIndex=0;
 canvas.addEventListener('pointerdown',e=>{if(!['select','drag','compare','compare-flight'].includes(state)||pointer!==null||e.button>0)return;e.preventDefault();const p=position(e);if(isWaterLesson())return;if(lesson>0){if(state==='compare-flight')runComparison();pointer=e.pointerId;start=end=p;canvas.setPointerCapture(e.pointerId);return;}if(KanjiTraits.hitTest(own,p)){choose();return;}if(!selected){message(1,'まず青い文字をタップ','下にある「木」を選んでから、中央を引きます。');return;}if(Math.hypot(p.x-200,p.y-200)>176||KanjiTraits.hitTest(enemy,p)){message(2,'中央の空いている場所を引こう','文字の上では発射しません。中央の点線内から引いてみよう。');return;}pointer=e.pointerId;start=end=p;canvas.setPointerCapture(e.pointerId);});
